#!/usr/bin/env python3
"""Install the repaired configuration-owned 4ndr0pac pair for the current user."""
import base64,hashlib,importlib.util,json,os,shutil,subprocess,sys,tempfile,zlib
from pathlib import Path
PAYLOAD=''
PAYLOAD_SHA='f7f065a83fc1cae682000e4f9ebfdb5b89768fdb834e6d9adf0d8c3ce391a75b'
def require(ok,msg):
 if not ok:raise RuntimeError(msg)
def files():
 raw=zlib.decompress(base64.b64decode(PAYLOAD,validate=True));require(hashlib.sha256(raw).hexdigest()==PAYLOAD_SHA,'Payload mismatch')
 entries=json.loads(raw);require(set(entries)=={'4ndr0pac','4ndr0pac.sh'},'Unexpected payload')
 return {name:base64.b64decode(value,validate=True) for name,value in entries.items()}
def install(home,config,data):
 target=config/'4ndr0tools/4ndr0pac';alias=home/'.local/bin/4ndr0pac'
 for path in [target,*target.parents,alias.parent,*alias.parent.parents]:
  require(not path.is_symlink(),'Symlink directory requires review: '+str(path))
 require(not target.exists() or target.is_dir(),'Existing tool path is not a directory')
 target.parent.mkdir(parents=True,exist_ok=True);alias.parent.mkdir(parents=True,exist_ok=True)
 # Repeated application of the exact pair is a no-op.
 if target.is_dir() and all((target/n).is_file() and not (target/n).is_symlink() and (target/n).read_bytes()==raw for n,raw in data.items()) and alias.is_symlink() and alias.resolve()==(target/'4ndr0pac').resolve():
  return {'status':'ALREADY_INSTALLED','launcher':str(alias),'payload_sha256':PAYLOAD_SHA}
 work=Path(tempfile.mkdtemp(prefix='.4ndr0pac-repair-',dir=target.parent));work.chmod(0o700)
 stage=work/'candidate';stage.mkdir()
 if target.exists():shutil.copytree(target,stage,symlinks=True,dirs_exist_ok=True)
 for name,raw in data.items():
  p=stage/name
  if p.exists() or p.is_symlink():
   require(not p.is_dir() or p.is_symlink(),'Payload file is a directory: '+name);p.unlink()
  p.write_bytes(raw);p.chmod(0o755)
 compile(data['4ndr0pac'].decode(),'4ndr0pac','exec')
 subprocess.run(['bash','-n',str(stage/'4ndr0pac.sh')],check=True)
 for args in [['--version'],['--dry-run','Package Info','pacman']]:
  check=subprocess.run([sys.executable,str(stage/'4ndr0pac'),*args],capture_output=True,text=True,timeout=20)
  require(check.returncode==0,'Prepared frontend check failed: '+check.stderr)
 old=work/'previous';alias_old=alias.with_name('.4ndr0pac.before-'+work.name.removeprefix('.4ndr0pac-repair-'))
 alias_tmp=alias.with_name('.4ndr0pac.new-'+work.name.removeprefix('.4ndr0pac-repair-'))
 require(not alias_old.exists() and not alias_old.is_symlink() and not alias_tmp.exists() and not alias_tmp.is_symlink(),'Alias recovery collision')
 record={'status':'PREPARED','target':str(target),'launcher':str(alias),'previous':str(old),'previous_launcher':str(alias_old),'payload_sha256':PAYLOAD_SHA}
 (work/'repair.json').write_text(json.dumps(record,indent=2)+'\n')
 moved=False;linked=False;target_moved=False
 try:
  if target.exists():target.rename(old);target_moved=True
  stage.rename(target);moved=True
  if alias.exists() or alias.is_symlink():alias.rename(alias_old);linked=True
  alias_tmp.symlink_to(target/'4ndr0pac');alias_tmp.replace(alias)
  check=subprocess.run([str(alias),'--version'],capture_output=True,text=True,timeout=20)
  require(check.returncode==0,'Installed frontend check failed')
 except BaseException:
  if alias_tmp.is_symlink():alias_tmp.unlink()
  if alias.is_symlink() and alias.readlink()==target/'4ndr0pac':alias.unlink()
  if linked:alias_old.rename(alias)
  if moved:target.rename(work/'failed-candidate')
  if target_moved:old.rename(target)
  raise
 record['status']='INSTALLED';record['version']=check.stdout.strip();record['recovery_directory']=str(work)
 (work/'repair.json').write_text(json.dumps(record,indent=2)+'\n');return record

def main():
 require(os.geteuid()!=0,'Run as your normal user, without sudo')
 require(importlib.util.find_spec('prompt_toolkit') is not None,'Install python-prompt-toolkit first; no files changed')
 home=Path.home();config=Path(os.environ.get('XDG_CONFIG_HOME',str(home/'.config'))).expanduser();require(config.is_absolute(),'Config directory must be absolute')
 os.umask(0o077);result=install(home,config,files());print(json.dumps(result,indent=2))
 print('Launch the repaired UI: '+str(home/'.local/bin/4ndr0pac'))
 print('No package-manager operation was executed.')
 return 0
if __name__=='__main__':
 try:sys.exit(main())
 except (OSError,ValueError,RuntimeError,subprocess.SubprocessError) as e:print('Stopped: '+str(e),file=sys.stderr);sys.exit(1)
